return $input.all().map(item => ({
  json: {
    advertiser: item.json.advertiserName || '',
    format: item.json.format || '',
    headline: item.json.headline || '',
    description: item.json.description || '',
    display_url: item.json.displayUrl || '',
    first_shown: item.json.firstShown || '',
    ad_url: item.json.adUrl || '',
    logged_at: new Date().toISOString()
  }
}));
